SELECT a.idx, a.type, a.req_type, a.status, a.name, a.email, a.mobile, a.title, a.file_name, a.file_path, a.reg_ip, a.reg_date, a.mod_date, a.del_yn, a.content, a.password, a.address, a.address_detail, a.zipcode, a.prod_type, a.esg_type, b.p_idx, b.dm_lang, b.dm_status, b.dm_text, b.dm_id, b.dm_name, b.dm_date, b.dm_ip, b.emailYN FROM voc a, voc_answers b WHERE a.idx = b.p_idx AND a.del_yn = 'N'
AND (title like CONCAT('%', #{keyword}, '%') OR content like CONCAT('%', #{keyword}, '%'))
AND title like CONCAT('%', #{keyword}, '%')
AND content like CONCAT('%', #{keyword}, '%')
AND req_type = #{req_type}
AND prod_type = #{prod_type}
AND status = #{status}
AND type = #{type}
AND type = #{searchType}
AND type in(2,3)
AND email = #{email}
ORDER BY a.idx DESC, b.dm_date DESC LIMIT #{pagination.limitStart}, #{recordSize}

